import { createPinia } from 'pinia';
import { createApp, watch } from 'vue';
import App from './App.vue';
import {
  GREETING_INDEX_GLOBAL_KEY,
  GREETING_INDEX_SCRIPT_NAME,
  isGreetingIndexMessage,
  type GreetingIndexGlobalApi,
} from './protocol';
import { useGreetingIndexStore } from './store';

const HOST_IFRAME_ID = 'dhl-greeting-index-host';
const NATIVE_FLOOR0_TRIGGER_ID = 'dhl-native-floor0-greeting-btn';
const BUTTON_RETRY_INTERVAL_MS = 1500;
const BUTTON_RETRY_MAX_ATTEMPTS = 12;

function resolveFontAwesomeHrefs(): string[] {
  const urls = new Set<string>();
  try {
    const parentLinks = Array.from(window.parent.document.querySelectorAll<HTMLLinkElement>('link[rel="stylesheet"]'));
    for (const link of parentLinks) {
      const href = link.href;
      if (href && /(?:fontawesome|font-awesome|\/css\/(?:solid|regular|brands)(?:\.min)?\.css)/i.test(href)) {
        urls.add(href);
      }
    }
  } catch {
    // ignore parent document read failure
  }
  // 同时引入与酒馆助手 iframe 相同的完整 FontAwesome 样式表，兼容 FA6/FA7 全部新增图标
  urls.add('https://testingcf.jsdelivr.net/npm/@fortawesome/fontawesome-free/css/all.min.css');
  return [...urls];
}

function buildHostSrcdoc(): string {
  const baseHref = (() => {
    try {
      return `${window.parent.location.origin}/`;
    } catch {
      return '/';
    }
  })();
  const faLinks = resolveFontAwesomeHrefs()
    .map(href => `<link rel="stylesheet" href="${href}" />`)
    .join('\n');
  return `<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8" />
<base href="${baseHref}" />
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />
${faLinks}
<style>
*,*::before,*::after{box-sizing:border-box;}
html,body{margin:0!important;padding:0!important;width:100%;height:100%;overflow:hidden!important;background:transparent!important;}
#app{width:100%;height:100%;}
</style>
</head>
<body><div id="app"></div></body>
</html>`;
}

function syncStylesToTargetHead(targetHead: HTMLHeadElement): () => void {
  const syncNow = () => {
    targetHead.querySelectorAll('[data-dhl-greeting-style="true"]').forEach(node => node.remove());
    document.head.querySelectorAll('style').forEach(styleEl => {
      const clone = styleEl.cloneNode(true) as HTMLStyleElement;
      clone.setAttribute('data-dhl-greeting-style', 'true');
      targetHead.appendChild(clone);
    });
  };

  syncNow();
  const observer = new MutationObserver(() => syncNow());
  observer.observe(document.head, { childList: true, subtree: true, characterData: true });
  return () => observer.disconnect();
}

function ensureButtonVisible(): boolean {
  try {
    const current = getScriptButtons();
    const hasButton = current.some(button => button.name === GREETING_INDEX_SCRIPT_NAME);
    const next = hasButton
      ? current.map(button => (button.name === GREETING_INDEX_SCRIPT_NAME ? { ...button, visible: true } : button))
      : [...current, { name: GREETING_INDEX_SCRIPT_NAME, visible: true }];
    replaceScriptButtons(next);
    appendInexistentScriptButtons([{ name: GREETING_INDEX_SCRIPT_NAME, visible: true }]);
    return getScriptButtons().some(button => button.name === GREETING_INDEX_SCRIPT_NAME && button.visible);
  } catch {
    return false;
  }
}

function setupButtonRegistrationRetry(): number {
  let attempts = 0;
  const timer = window.setInterval(() => {
    attempts += 1;
    const ok = ensureButtonVisible();
    if (ok || attempts >= BUTTON_RETRY_MAX_ATTEMPTS) {
      window.clearInterval(timer);
    }
  }, BUTTON_RETRY_INTERVAL_MS);
  return timer;
}

$(() => {
  errorCatched(() => {
    const parentWin = window.parent;
    const parentDoc = parentWin.document;
    const originalRequestAnimationFrame = window.requestAnimationFrame;
    const originalCancelAnimationFrame = window.cancelAnimationFrame;

    // Vue 在隐藏的脚本 iframe 中运行；Firefox 会暂停这里的动画帧，导致外部弹窗一直透明。
    // 将动画调度交给可见的酒馆窗口，让弹窗及其子弹窗的过渡都能完成。
    window.requestAnimationFrame = parentWin.requestAnimationFrame.bind(parentWin);
    window.cancelAnimationFrame = parentWin.cancelAnimationFrame.bind(parentWin);

    parentDoc.getElementById(HOST_IFRAME_ID)?.remove();

    const pinia = createPinia();
    const app = createApp(App).use(pinia);
    const store = useGreetingIndexStore(pinia);

    const hostIframe = parentDoc.createElement('iframe');
    hostIframe.id = HOST_IFRAME_ID;
    hostIframe.setAttribute('script_id', getScriptId());
    hostIframe.setAttribute('frameborder', '0');
    hostIframe.setAttribute('title', '灯火阑珊·开场白选定');
    Object.assign(hostIframe.style, {
      position: 'fixed',
      inset: '0',
      width: '100%',
      height: '100dvh',
      border: '0',
      margin: '0',
      padding: '0',
      zIndex: '2147483000',
      background: 'transparent',
      display: 'none',
      pointerEvents: 'none',
    });
    const hostBlobUrl = URL.createObjectURL(new Blob([buildHostSrcdoc()], { type: 'text/html;charset=utf-8' }));
    hostIframe.src = hostBlobUrl;

    let stopStyleSync: (() => void) | null = null;
    let mounted = false;
    let hideTimer: number | null = null;

    hostIframe.addEventListener('load', () => {
      if (mounted || !hostIframe.contentDocument) return;
      mounted = true;
      stopStyleSync = syncStylesToTargetHead(hostIframe.contentDocument.head);
      const mountRoot = hostIframe.contentDocument.getElementById('app') ?? hostIframe.contentDocument.body;
      app.mount(mountRoot);
    });

    parentDoc.body.appendChild(hostIframe);

    const stopVisibilityWatch = watch(
      () => store.visible,
      visible => {
        if (hideTimer !== null) {
          window.clearTimeout(hideTimer);
          hideTimer = null;
        }
        if (visible) {
          hostIframe.style.display = 'block';
          hostIframe.style.pointerEvents = 'auto';
          window.setTimeout(() => hostIframe.contentWindow?.focus(), 20);
        } else {
          hostIframe.style.pointerEvents = 'none';
          hideTimer = window.setTimeout(() => {
            if (!store.visible) {
              hostIframe.style.display = 'none';
            }
          }, 200);
        }
      },
      { immediate: true },
    );

    const api: GreetingIndexGlobalApi = {
      version: 2,
      open: options => store.open(options),
      close: () => store.close(),
      toggle: options => store.toggle(options),
      isOpen: () => store.visible,
    };

    initializeGlobal(GREETING_INDEX_GLOBAL_KEY, api);
    (parentWin as unknown as Record<string, unknown>)[GREETING_INDEX_GLOBAL_KEY] = api;

    const onParentMessage = (event: MessageEvent<unknown>) => {
      if (!isGreetingIndexMessage(event.data)) return;
      if (event.data.type === 'open') {
        void store.open(event.data.options);
      } else if (event.data.type === 'close') {
        store.close();
      } else if (event.data.type === 'toggle') {
        void store.toggle(event.data.options);
      }
    };

    const onParentStorage = (event: StorageEvent) => {
      if (!event.key || event.key.includes('theme') || event.key.includes('preferences')) {
        store.syncTheme();
      }
    };

    parentWin.addEventListener('message', onParentMessage);
    parentWin.addEventListener('storage', onParentStorage);

    ensureButtonVisible();
    const retryTimer = setupButtonRegistrationRetry();

    // 当第 0 层为纯文本引导页（尚未挂载伪同层舞台）时，在原生第 0 层顶部嵌入快捷展卷按钮
    const syncNativeFloorZeroTrigger = () => {
      try {
        const existing = parentDoc.getElementById(NATIVE_FLOOR0_TRIGGER_ID);
        const isPseudoActive = parentDoc.body.classList.contains('dhl-pseudo-stage-root-active');
        const lastId = getLastMessageId();
        const mes0Text = parentDoc.querySelector<HTMLElement>('#chat .mes[mesid="0"] .mes_text');
        const hasGreetings = (() => {
          const v2 = getCharData('current')?.data as Partial<SillyTavern.v2CharData> | undefined;
          return Array.isArray(v2?.alternate_greetings) && v2.alternate_greetings.length > 1;
        })();

        if (isPseudoActive || lastId !== 0 || !mes0Text || !hasGreetings) {
          existing?.remove();
          return;
        }
        if (existing && mes0Text.parentElement?.contains(existing)) return;
        existing?.remove();

        const btn = parentDoc.createElement('button');
        btn.id = NATIVE_FLOOR0_TRIGGER_ID;
        btn.type = 'button';
        btn.innerHTML = '<i class="fa-solid fa-book-bookmark"></i><span>展开红颜画卷 · 选定开局序章</span>';
        Object.assign(btn.style, {
          display: 'inline-flex',
          alignItems: 'center',
          gap: '8px',
          margin: '6px 0 12px',
          padding: '8px 16px',
          border: '1px solid rgba(227, 185, 111, 0.55)',
          borderRadius: '999px',
          background: 'linear-gradient(135deg, rgba(20, 39, 46, 0.92), rgba(45, 31, 25, 0.92))',
          color: '#f5dfb5',
          fontSize: '13px',
          fontWeight: '600',
          letterSpacing: '0.04em',
          cursor: 'pointer',
          boxShadow: '0 6px 20px rgba(0, 0, 0, 0.28)',
        });
        btn.addEventListener('click', () => {
          void store.open();
        });
        mes0Text.parentElement?.insertBefore(btn, mes0Text);
      } catch {
        // ignore DOM sync errors
      }
    };

    syncNativeFloorZeroTrigger();
    const nativeTriggerTimer = window.setInterval(syncNativeFloorZeroTrigger, 900);

    const eventStops: Array<() => void> = [];
    eventStops.push(
      eventOn(getButtonEvent(GREETING_INDEX_SCRIPT_NAME), () => {
        void store.open();
      }).stop,
    );
    eventStops.push(
      eventOn(tavern_events.CHAT_CHANGED, () => {
        ensureButtonVisible();
        void store.refreshCatalog(true);
        window.setTimeout(syncNativeFloorZeroTrigger, 120);
      }).stop,
    );
    eventStops.push(
      eventOn(tavern_events.MESSAGE_SWIPED, () => {
        store.refreshRuntime();
        window.setTimeout(syncNativeFloorZeroTrigger, 80);
      }).stop,
    );
    eventStops.push(
      eventOn(tavern_events.MESSAGE_DELETED, () => {
        store.refreshRuntime();
        window.setTimeout(syncNativeFloorZeroTrigger, 80);
      }).stop,
    );
    eventStops.push(
      eventOn(tavern_events.MESSAGE_RECEIVED, () => {
        store.refreshRuntime();
        window.setTimeout(syncNativeFloorZeroTrigger, 80);
      }).stop,
    );

    $(window).on('pagehide', () => {
      window.clearInterval(retryTimer);
      window.clearInterval(nativeTriggerTimer);
      if (hideTimer !== null) window.clearTimeout(hideTimer);
      stopVisibilityWatch();
      stopStyleSync?.();
      eventStops.forEach(stop => stop());
      parentWin.removeEventListener('message', onParentMessage);
      parentWin.removeEventListener('storage', onParentStorage);
      if ((parentWin as unknown as Record<string, unknown>)[GREETING_INDEX_GLOBAL_KEY] === api) {
        delete (parentWin as unknown as Record<string, unknown>)[GREETING_INDEX_GLOBAL_KEY];
      }
      if (mounted) {
        app.unmount();
      }
      parentDoc.getElementById(NATIVE_FLOOR0_TRIGGER_ID)?.remove();
      hostIframe.remove();
      URL.revokeObjectURL(hostBlobUrl);
      window.requestAnimationFrame = originalRequestAnimationFrame;
      window.cancelAnimationFrame = originalCancelAnimationFrame;
    });

    console.info('[开场白索引] 独立红颜画卷选定器已就绪');
  })();
});
