interface IndexSummaryItem {
  openingLabel: string;
  heroineName: string;
  subtitle: string;
  summary: string;
}

function normalizeSpace(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

function stripUserMacro(text: string): string {
  return text.replace(/\{\{user\}\}|<user>/gi, '你');
}

function sanitizeLegacyHeroineText(heroineName: string | null, text: string): string {
  if (heroineName !== '白清弦' || !text) return text;
  return text
    .replace(/琴剑双绝|琴剑双修/g, '剑道通神')
    .replace(/以琴音剑意/g, '以天金剑气')
    .replace(/清弦琴剑/g, '戮天剑');
}

function compactTraitLabel(text: string, maxLen = 12): string {
  const stripped = text.replace(/\s*[（(][^）)]*[）)]/g, '').trim() || text.trim();
  return stripped.length > maxLen ? stripped.slice(0, maxLen) + '…' : stripped;
}

function levelToRealmText(level: number | null | undefined): string {
  if (typeof level !== 'number' || !Number.isFinite(level)) return '';
  if (level <= 0) return '凡胎待定';
  const clamped = Math.max(1, Math.min(48, Math.floor(level)));
  const major = REALM_NAMES[Math.floor((clamped - 1) / 4)] ?? '未知';
  const minor = REALM_STAGES[(clamped - 1) % 4] ?? '';
  return major + minor;
}

function inferColorFromRealmText(realmText: string): string {
  for (let i = 0; i < REALM_NAMES.length; i += 1) {
    if (realmText.includes(REALM_NAMES[i])) {
      return getRealmColor(i * 4 + 1);
    }
  }
  return '#d9b56d';
}

function canonicalizeHeroineName(rawName: string): string | null {
  const trimmed = rawName.trim();
  if (!trimmed) return null;
  if (trimmed in COMPANION_CANONICAL_NAMES) return COMPANION_CANONICAL_NAMES[trimmed];
  if (trimmed in STATIC_HEROINE_FALLBACKS || trimmed in CHARACTER_IMAGE_POOLS) return trimmed;
  for (const name of HEROINE_ORDER) {
    if (trimmed.includes(name)) return name;
    const aliases = COMPANION_ALIASES_BY_CANONICAL[name] ?? [];
    if (aliases.some(alias => trimmed.includes(alias))) return name;
  }
  return null;
}

function isRegularPool(pool: unknown): pool is CharacterImagePool {
  if (!pool || typeof pool !== 'object') return false;
  const candidate = pool as Partial<CharacterImagePool>;
  return Array.isArray(candidate.front) && Array.isArray(candidate.back);
}

function resolveHeroineImages(name: string, customPortraits: Record<string, { front?: string; back?: string }>): {
  frontImages: string[];
  backImages: string[];
  dualSoulPortraits?: DualSoulPortraits;
} {
  const custom = customPortraits[name];
  if (custom && (custom.front || custom.back)) {
    const front = custom.front ? [custom.front] : custom.back ? [custom.back] : [];
    const back = custom.back ? [custom.back] : front;
    if (front.length > 0) return { frontImages: front, backImages: back };
  }

  const pool = CHARACTER_IMAGE_POOLS[name];
  if (!pool) return { frontImages: [], backImages: [] };
  if (isRegularPool(pool)) {
    return {
      frontImages: [...pool.front],
      backImages: pool.back.length > 0 ? [...pool.back] : [...pool.front],
    };
  }

  const dual = pool as DualSoulImagePool;
  const yuxiFront = [...(dual.虞汐_front ?? [])];
  const yuxiBack = [...(dual.虞汐_back ?? [])];
  const yuyanFront = [...(dual.虞颜_front ?? [])];
  const yuyanBack = [...(dual.虞颜_back ?? [])];
  return {
    frontImages: [...yuxiFront, ...yuyanFront],
    backImages: [...yuyanBack, ...yuxiBack],
    dualSoulPortraits: {
      虞汐: { front: yuxiFront, back: yuxiBack.length > 0 ? yuxiBack : yuxiFront },
      虞颜: { front: yuyanFront, back: yuyanBack.length > 0 ? yuyanBack : yuyanFront },
    },
  };
}

function parseIndexGuideContent(rawText: string): { guideNote: string; summaries: IndexSummaryItem[] } {
  const cleaned = parseMessageContent(rawText).narrative;
  const lines = cleaned
    .split(/\r?\n/)
    .map(line => line.trim())
    .filter(Boolean);

  const guideNotes: string[] = [];
  const summaries: IndexSummaryItem[] = [];
  let pendingHeader: { openingLabel: string; heroineName: string; subtitle: string } | null = null;

  for (const line of lines) {
    const plain = line.replace(/^\*+|\*+$/g, '').trim();
    if (!plain || plain === '索引页') continue;
    if (plain.startsWith('游玩须知') || plain.includes('请点击下方开场白索引')) {
      guideNotes.push(plain);
      continue;
    }

    const headerMatch = plain.match(/^(开局[一二三四五六七八九十百零\d]+)\s*[-·—]\s*([^:：]+?)\s*[:：]\s*(.+)$/u);
    if (headerMatch) {
      const rawHeroine = headerMatch[2].trim();
      pendingHeader = {
        openingLabel: headerMatch[1].trim(),
        heroineName: canonicalizeHeroineName(rawHeroine) ?? rawHeroine,
        subtitle: headerMatch[3].trim(),
      };
      continue;
    }

    if (pendingHeader) {
      const rawSummary = plain.replace(/^[“"「『]+|[”"」』]+$/g, '').trim();
      const summary = sanitizeLegacyHeroineText(pendingHeader.heroineName, stripUserMacro(rawSummary));
      summaries.push({
        ...pendingHeader,
        summary,
      });
      pendingHeader = null;
    }
  }

  return {
    guideNote: guideNotes.join(' · '),
    summaries,
  };
}

function parseVisualCardFromRaw(rawContent: string): { speaker: string; quote: string } {
  const regex = /<\s*visual_cards\b[^>]*>([\s\S]*?)<\s*\/\s*visual_cards\s*>/gi;
  let lastPayload = '';
  let match: RegExpExecArray | null;
  while ((match = regex.exec(rawContent)) !== null) {
    lastPayload = match[1] ?? '';
  }
  if (!lastPayload.trim()) return { speaker: '', quote: '' };

  try {
    const parsed = JSON.parse(lastPayload.trim()) as unknown;
    const list = Array.isArray(parsed) ? parsed : [parsed];
    const first = list.find(item => item && typeof item === 'object') as Record<string, unknown> | undefined;
    if (first) {
      return {
        speaker: String(first.name ?? '').trim(),
        quote: stripUserMacro(String(first.back_text ?? '').trim()),
      };
    }
  } catch {
    const quoteMatch = lastPayload.match(/"back_text"\s*:\s*"([^"]+)"/);
    const nameMatch = lastPayload.match(/"name"\s*:\s*"([^"]+)"/);
    return {
      speaker: nameMatch?.[1]?.trim() ?? '',
      quote: stripUserMacro(quoteMatch?.[1]?.trim() ?? ''),
    };
  }

  return { speaker: '', quote: '' };
}

function parseInitVarFromRaw(rawContent: string, heroineName: string | null): {
  protagonist: ProtagonistPresetSummary | null;
  heroineInitial: HeroineOpeningRelation | null;
  mentionedHeroines: string[];
} {
  const initMatch = rawContent.match(/<initvar>([\s\S]*?)<\/initvar>/i);
  if (!initMatch?.[1]) {
    return { protagonist: null, heroineInitial: null, mentionedHeroines: [] };
  }

  try {
    const doc = YAML.parse(initMatch[1]) as Record<string, any> | null;
    if (!doc || typeof doc !== 'object') {
      return { protagonist: null, heroineInitial: null, mentionedHeroines: [] };
    }

    const self = (doc.本尊 ?? {}) as Record<string, any>;
    const track = (self.行踪 ?? {}) as Record<string, any>;
    const identity = (self.身份 ?? {}) as Record<string, any>;
    const clock = (doc.世界时钟 ?? {}) as Record<string, any>;
    const rawLevel = typeof self.等级 === 'number' ? self.等级 : Number(self.等级);
    const level = Number.isFinite(rawLevel) ? rawLevel : null;
    const realmLabel = String(self.境界描述 || '').trim() || levelToRealmText(level) || '待定';
    const spiritRoot = String(self.灵根 || '待定').trim();
    const physique = String(self.体质 || '待定').trim();
    const sect = String(identity.宗门 || '').trim();
    const origin = String(identity.出身 || '').trim();
    const location = String(track.当前区域 || '').trim();
    const technique = String(self.功法 || '').trim();
    const weapon = String(self.本命兵器 || '').trim();
    const era = String(clock.纪元 || '').replace('末法时代', '盛法时代').trim();
    const eraTime = [era, clock.年份 ? '第' + String(clock.年份) + '年' : '', String(clock.时辰 || '').trim()]
      .filter(Boolean)
      .join(' · ');

    const rawOpps = Array.isArray(doc['$可参与机遇']) ? doc['$可参与机遇'] : [];
    const opportunities = rawOpps
      .map((item: any) => stripUserMacro(String(item?.标题 || '').trim()))
      .filter(Boolean);
    const currentSituation = stripUserMacro(String(doc.当前处境 || '').trim());

    const companions = (doc.红颜 ?? {}) as Record<string, any>;
    const mentionedHeroines = Object.keys(companions)
      .map(key => canonicalizeHeroineName(key))
      .filter((name): name is string => Boolean(name));

    let heroineInitial: HeroineOpeningRelation | null = null;
    if (heroineName && companions[heroineName] && typeof companions[heroineName] === 'object') {
      const entry = companions[heroineName];
      const hLevel = typeof entry.等级 === 'number' ? entry.等级 : Number(entry.等级);
      const favor = typeof entry.好感度 === 'number' ? entry.好感度 : Number(entry.好感度);
      heroineInitial = {
        favor: Number.isFinite(favor) ? favor : null,
        relation: String(entry.关系 || '').trim(),
        realmLabel: String(entry.境界描述 || '').trim() || (Number.isFinite(hLevel) ? levelToRealmText(hLevel) : ''),
      };
    }

    return {
      protagonist: {
        level,
        realmLabel,
        realmColor: level !== null && level > 0 ? getRealmColor(level) : inferColorFromRealmText(realmLabel),
        spiritRoot,
        shortSpiritRoot: compactTraitLabel(spiritRoot, 12),
        rootColor: getRootColor(spiritRoot),
        physique,
        shortPhysique: compactTraitLabel(physique, 12),
        sect,
        shortSect: compactTraitLabel(sect, 12),
        origin,
        location,
        eraTime,
        technique,
        weapon,
        opportunityCount: opportunities.length,
        opportunities,
        currentSituation,
      },
      heroineInitial,
      mentionedHeroines,
    };
  } catch {
    // 若手写 initvar 存在局部缩进瑕疵，使用行级正则兜底提取本尊核心初始设定
    const raw = initMatch[1];
    const selfBlock = raw.split(/\n(?:红颜角色库|红颜|NPC图鉴|任务列表)\s*:/)[0] ?? raw;
    const pickField = (key: string): string => {
      const m = selfBlock.match(new RegExp('^\\s*' + key + '\\s*:\\s*["' + "'" + ']?([^"' + "'" + '\r\n#]+)["' + "'" + ']?', 'm'));
      return stripUserMacro(m?.[1]?.trim() ?? '');
    };
    const lvRaw = Number(pickField('等级'));
    const level = Number.isFinite(lvRaw) && pickField('等级') !== '' ? lvRaw : null;
    const realmLabel = pickField('境界描述') || levelToRealmText(level) || '待定';
    const spiritRoot = pickField('灵根') || '待定';
    const physique = pickField('体质') || '待定';
    const sect = pickField('宗门');
    const origin = pickField('出身');
    const location = pickField('当前区域');
    const currentSituation = (() => {
      const m = raw.match(/^\s*当前处境\s*:\s*["'`]?([^"'`\r\n]+)["'`]?/m);
      return stripUserMacro(m?.[1]?.trim() ?? '');
    })();
    return {
      protagonist: {
        level,
        realmLabel,
        realmColor: level !== null && level > 0 ? getRealmColor(level) : inferColorFromRealmText(realmLabel),
        spiritRoot,
        shortSpiritRoot: compactTraitLabel(spiritRoot, 12),
        rootColor: getRootColor(spiritRoot),
        physique,
        shortPhysique: compactTraitLabel(physique, 12),
        sect,
        shortSect: compactTraitLabel(sect, 12),
        origin,
        location,
        eraTime: '',
        technique: pickField('功法'),
        weapon: pickField('本命兵器'),
        opportunityCount: 0,
        opportunities: [],
        currentSituation,
      },
      heroineInitial: null,
      mentionedHeroines: [],
    };
  }
}

function computeTextOverlapScore(summaryText: string, bodyText: string): number {
  const cleanSummary = summaryText.replace(/[^\u4e00-\u9fa5a-zA-Z0-9]/g, '');
  const cleanBody = bodyText.replace(/[^\u4e00-\u9fa5a-zA-Z0-9]/g, '');
  if (!cleanSummary || !cleanBody) return 0;

  let hits = 0;
  const seen = new Set<string>();
  for (let i = 0; i <= cleanSummary.length - 2; i += 1) {
    const token = cleanSummary.slice(i, i + 2);
    if (seen.has(token)) continue;
    seen.add(token);
    if (cleanBody.includes(token)) hits += 1;
  }
  return hits;
}

function attachGuideSummaries(openings: GreetingOpeningEntry[], summaries: IndexSummaryItem[]): void {
  const usedSummaryIndices = new Set<number>();
  const byHeroine = new Map<string, GreetingOpeningEntry[]>();

  for (const opening of openings) {
    if (opening.kind !== 'heroine' || !opening.heroineName) continue;
    const group = byHeroine.get(opening.heroineName) ?? [];
    group.push(opening);
    byHeroine.set(opening.heroineName, group);
  }

  for (const [heroineName, heroineOpenings] of byHeroine.entries()) {
    const candidateIndices = summaries
      .map((item, idx) => ({ item, idx }))
      .filter(({ item, idx }) => !usedSummaryIndices.has(idx) && item.heroineName === heroineName);

    if (candidateIndices.length === 0) continue;
    if (heroineOpenings.length === 1 && candidateIndices.length === 1) {
      const matched = candidateIndices[0];
      usedSummaryIndices.add(matched.idx);
      heroineOpenings[0].subtitle = matched.item.subtitle;
      heroineOpenings[0].summary = matched.item.summary;
      continue;
    }

    const pairs: Array<{ opening: GreetingOpeningEntry; summaryIdx: number; item: IndexSummaryItem; score: number }> = [];
    for (const opening of heroineOpenings) {
      const bodyRef = opening.narrative + ' ' + (opening.protagonist?.currentSituation ?? '') + ' ' + (opening.protagonist?.location ?? '');
      for (const { item, idx } of candidateIndices) {
        const overlap = computeTextOverlapScore(item.subtitle + item.summary, bodyRef);
        const labelBonus = opening.openingLabel && opening.openingLabel === item.openingLabel ? 3 : 0;
        pairs.push({ opening, summaryIdx: idx, item, score: overlap * 2 + labelBonus });
      }
    }
    pairs.sort((a, b) => b.score - a.score);
    const assignedOpenings = new Set<number>();
    for (const pair of pairs) {
      if (assignedOpenings.has(pair.opening.index) || usedSummaryIndices.has(pair.summaryIdx)) continue;
      assignedOpenings.add(pair.opening.index);
      usedSummaryIndices.add(pair.summaryIdx);
      pair.opening.subtitle = pair.item.subtitle;
      pair.opening.summary = pair.item.summary;
    }
  }
}

interface ParsedWorldbookLore {
  tagline?: string;
  epithet?: string;
  realm?: string;
  spiritRoot?: string;
  physique?: string;
  affiliation?: string;
  weapon?: string;
  ageDesc?: string;
  appearanceNote?: string;
  temperamentNote?: string;
}

function cleanLoreValue(raw: string): string {
  return stripUserMacro(raw)
    .replace(/^[：:\s]+/, '')
    .replace(/（[^）]{18,}）/g, '')
    .replace(/\([^)]{18,}\)/g, '')
    .trim();
}

function extractSectionSnippet(content: string, sectionPattern: RegExp, maxLen = 110): string {
  const lines = content.split(/\r?\n/);
  let inSection = false;
  const collected: string[] = [];

  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line || line === '---') continue;
    if (/^【.+?】/.test(line)) {
      if (inSection) break;
      if (sectionPattern.test(line)) {
        inSection = true;
      }
      continue;
    }
    if (!inSection) continue;
    const cleaned = stripUserMacro(line.replace(/^[-*•]\s*/, '').replace(/^[^：:]{1,8}[：:]\s*/, '')).trim();
    if (cleaned.length < 4 || cleaned.startsWith('⚠️')) continue;
    collected.push(cleaned);
    if (collected.join(' ').length >= maxLen) break;
  }

  const merged = collected.join(' ');
  return merged.length > maxLen ? merged.slice(0, maxLen).replace(/[，、；,.\s]+$/, '') + '……' : merged;
}

function parseRoleWorldbookEntry(content: string): ParsedWorldbookLore {
  const lore: ParsedWorldbookLore = {};
  const segments = content
    .split(/\r?\n/)
    .flatMap(line => line.split('｜'))
    .map(part => part.trim())
    .filter(Boolean);

  for (const seg of segments) {
    const match = seg.match(/^([^：:\s]{2,6})[：:]\s*(.+)$/);
    if (!match) continue;
    const key = match[1].trim();
    const value = cleanLoreValue(match[2]);
    if (!value) continue;

    if (!lore.epithet && /^(?:尊号|道号|小字与仙号|化名|小字|身份)$/.test(key)) {
      lore.epithet = value.split(/[（(；;。]/)[0].trim();
    } else if (!lore.realm && /^(?:修为|境界)$/.test(key)) {
      lore.realm = value.split(/[（(｜]/)[0].trim();
    } else if (!lore.spiritRoot && /^(?:灵根|根基|血脉)$/.test(key)) {
      lore.spiritRoot = value.split(/[（(；;。]/)[0].trim();
    } else if (!lore.physique && /^(?:道体|体质)$/.test(key)) {
      lore.physique = value.split(/[（(；;。]/)[0].trim();
    } else if (!lore.affiliation && /^(?:宗属|所属|居地|归属|尊位)$/.test(key)) {
      lore.affiliation = value.split(/[（(；;。]/)[0].trim();
    } else if (!lore.weapon && /^(?:本命|本命法宝|兵器|法宝)$/.test(key)) {
      lore.weapon = value.split(/[（(｜；;。]/)[0].trim();
    } else if (!lore.ageDesc && /^(?:寿数|年岁|寿元)$/.test(key)) {
      lore.ageDesc = value;
    }
  }

  lore.appearanceNote = extractSectionSnippet(content, /仙姿|仪容|容色/, 108);
  lore.temperamentNote = extractSectionSnippet(content, /性情|性格|风骨/, 108);
  return lore;
}

async function loadWorldbookHeroineLore(): Promise<{ worldbookName: string; loreByHeroine: Map<string, ParsedWorldbookLore> }> {
  const loreByHeroine = new Map<string, ParsedWorldbookLore>();
  let primaryName = '';
  try {
    const wbNames = getCharWorldbookNames('current');
    primaryName = wbNames?.primary ?? '';
    const candidates = [wbNames?.primary, ...(wbNames?.additional ?? [])].filter((item): item is string => Boolean(item));
    if (candidates.length === 0) return { worldbookName: '', loreByHeroine };

    const entries = await getWorldbook(candidates[0]);
    for (const entry of entries) {
      const entryName = String(entry.name || '').trim();
      const content = String(entry.content || '');
      if (!content) continue;

      if (entryName.includes('红颜索引') || entryName.includes('红颜简介')) {
        for (const line of content.split(/\r?\n/)) {
          const m = line.trim().match(/^([^:：#\s]{2,6})\s*[:：]\s*(.+)$/);
          if (!m) continue;
          const canonical = canonicalizeHeroineName(m[1]);
          if (!canonical) continue;
          const prev = loreByHeroine.get(canonical) ?? {};
          prev.tagline = sanitizeLegacyHeroineText(canonical, stripUserMacro(m[2].trim()));
          loreByHeroine.set(canonical, prev);
        }
        continue;
      }

      const roleMatch = entryName.match(/^\[角色\]\s*(.+)$/);
      if (roleMatch && !/(?:陌生期|好感期|好奇期|亲近期|心动期|依赖期|确认期|深爱期)$/.test(entryName)) {
        const canonical = canonicalizeHeroineName(roleMatch[1]);
        if (!canonical) continue;
        const parsed = parseRoleWorldbookEntry(content);
        const prev = loreByHeroine.get(canonical) ?? {};
        loreByHeroine.set(canonical, { ...parsed, ...prev, tagline: prev.tagline ?? parsed.tagline });
      }
    }
  } catch (error) {
    console.warn('[开场白索引] 读取世界书红颜档案失败，将使用静态兜底资料', error);
  }

  return { worldbookName: primaryName, loreByHeroine };
}

function readCustomPortraitOverrides(): Record<string, { front?: string; back?: string }> {
  try {
    const vars = getVariables({ type: 'message', message_id: 0 });
    const customLib = _.get(vars, 'stat_data.红颜角色库', null) as Record<string, any> | null;
    if (!customLib || typeof customLib !== 'object') return {};
    const out: Record<string, { front?: string; back?: string }> = {};
    for (const [name, item] of Object.entries(customLib)) {
      const front = String(item?.自定义立绘?.front ?? '').trim();
      const back = String(item?.自定义立绘?.back ?? '').trim();
      if (front || back) out[name] = { front, back };
    }
    return out;
  } catch {
    return {};
  }
}

function extractNarrativePreview(narrative: string, firstLine: string | undefined): string {
  const body = firstLine && /^(?:【|\[|\*\*\*)/.test(firstLine) ? narrative.replace(firstLine, '') : narrative;
  return stripUserMacro(normalizeSpace(body))
    .replace(/\*\*/g, '')
    .replace(/```[\s\S]*?```/g, '')
    .slice(0, 200);
}

let cachedKey = '';
let cachedCatalog: GreetingCatalog | null = null;

export async function loadGreetingCatalog(forceRefresh = false): Promise<GreetingCatalog> {
  const charData = getCharData('current');
  const characterName = String(charData?.name ?? '当前角色');
  const v2 = charData?.data as Partial<SillyTavern.v2CharData> | undefined;
  const alternates = Array.isArray(v2?.alternate_greetings) ? v2.alternate_greetings.map(item => String(item ?? '')) : [];
  const wbPrimary = (() => {
    try {
      return getCharWorldbookNames('current')?.primary ?? '';
    } catch {
      return '';
    }
  })();

  const signature = characterName + '::' + wbPrimary + '::' + String(alternates.length) + '::' + alternates.map(s => s.length).join(',');
  if (!forceRefresh && cachedCatalog && cachedKey === signature) {
    return cachedCatalog;
  }

  const { worldbookName, loreByHeroine } = await loadWorldbookHeroineLore();
  const customPortraits = readCustomPortraitOverrides();

  let guideNote = '';
  let guideSummaries: IndexSummaryItem[] = [];
  if (alternates[0] && /^\s*\*{2,}\s*索引页/.test(alternates[0])) {
    const parsedGuide = parseIndexGuideContent(alternates[0]);
    guideNote = parsedGuide.guideNote;
    guideSummaries = parsedGuide.summaries;
  }

  const openings: GreetingOpeningEntry[] = alternates.map((rawContent, offset) => {
    const index = offset + 1;
    const parsedMessage = parseMessageContent(rawContent);
    const narrative = stripUserMacro(parsedMessage.narrative.trim());
    const firstLine = rawContent
      .split(/\r?\n/)
      .map(line => line.trim())
      .find(Boolean);

    const isGuide = offset === 0 && Boolean(firstLine && /索引页/.test(firstLine));
    const bracketMatch = firstLine?.match(/^(?:\[(.+?)\]|【(.+?)】)/);
    const rawTitle = (bracketMatch?.[1] ?? bracketMatch?.[2] ?? normalizeSpace(firstLine ?? '').replace(/^\*+|\*+$/g, '').slice(0, 28)) || ('开场白 #' + String(index));

    const labelMatch = rawTitle.match(/^(开局[一二三四五六七八九十百零\d]+)\s*[-·—]\s*(.+)$/u);
    const openingLabel = isGuide ? '索引页' : labelMatch?.[1]?.trim() || ('序章 ' + String(index));
    const titleSuffix = labelMatch?.[2]?.trim() ?? '';

    const isCustom = !isGuide && (/自定义/.test(rawTitle) || /自定义/.test(titleSuffix));
    const cardQuote = parseVisualCardFromRaw(rawContent);
    const inferredHeroine =
      isGuide || isCustom
        ? null
        : canonicalizeHeroineName(titleSuffix) ?? canonicalizeHeroineName(cardQuote.speaker) ?? canonicalizeHeroineName(rawTitle);

    const kind: OpeningKind = isGuide ? 'guide' : isCustom ? 'custom' : 'heroine';
    const initInfo = parseInitVarFromRaw(rawContent, inferredHeroine);
    const secondaryHeroines = initInfo.mentionedHeroines.filter(name => name !== inferredHeroine);
    const preview = extractNarrativePreview(narrative, firstLine);
    const cleanBodyNarrative = firstLine && /^(?:【|\[|\*\*\*)/.test(firstLine)
      ? narrative.replace(stripUserMacro(firstLine), '').trim()
      : narrative;

    const defaultSummary = isGuide
      ? '角色卡内置导览页，汇总全部开局序章脉络与游玩文风提示。'
      : isCustom
        ? '自由设定本尊出身、境界、灵根与开场境遇，在「局设 → 开局预设」中随时定制专属仙途起点。'
        : initInfo.protagonist?.currentSituation || preview;

    const shortTitle = isGuide
      ? '开局导览索引页'
      : isCustom
        ? openingLabel + ' · 自由定制'
        : inferredHeroine
          ? openingLabel + ' · ' + inferredHeroine
          : rawTitle;

    return {
      index,
      kind,
      openingLabel,
      title: rawTitle,
      shortTitle,
      subtitle: isCustom ? '自定命格 · 万象由心' : isGuide ? '序章总目 · 游玩须知' : '',
      summary: defaultSummary,
      preview,
      narrative: cleanBodyNarrative,
      rawContent,
      searchText: [rawTitle, inferredHeroine ?? '', preview, initInfo.protagonist?.location ?? '', initInfo.protagonist?.sect ?? ''].join(' '),
      heroineName: inferredHeroine,
      secondaryHeroines,
      quote: cardQuote.quote,
      quoteSpeaker: cardQuote.speaker || (inferredHeroine ?? ''),
      protagonist: initInfo.protagonist,
      heroineInitial: initInfo.heroineInitial,
    };
  });

  attachGuideSummaries(openings, guideSummaries);
  for (const item of openings) {
    if (item.subtitle || item.summary) {
      item.searchText = [item.title, item.shortTitle, item.subtitle, item.summary, item.heroineName ?? '', item.protagonist?.location ?? '', item.protagonist?.sect ?? '', item.narrative.slice(0, 600)].join(' ');
    }
  }

  const discoveredNames = new Set<string>(HEROINE_ORDER);
  for (const key of Object.keys(CHARACTER_IMAGE_POOLS)) discoveredNames.add(key);
  for (const key of loreByHeroine.keys()) discoveredNames.add(key);
  for (const opening of openings) {
    if (opening.heroineName) discoveredNames.add(opening.heroineName);
  }

  const heroines: HeroineProfile[] = [...discoveredNames].map(name => {
    const fallback = STATIC_HEROINE_FALLBACKS[name];
    const lore = loreByHeroine.get(name);
    const heroineOpenings = openings.filter(item => item.kind === 'heroine' && item.heroineName === name);
    const images = resolveHeroineImages(name, customPortraits);
    const realm = lore?.realm || fallback?.realm || heroineOpenings[0]?.heroineInitial?.realmLabel || '境界未明';
    const tagline = lore?.tagline || fallback?.tagline || '红尘仙途之中静候相逢的佳人。';
    const derivedTags = fallback?.tags ?? tagline
      .split(/[，,；;。]/)
      .map(s => s.trim())
      .filter(s => s.length >= 2 && s.length <= 6)
      .slice(0, 4);

    return {
      name,
      epithet: lore?.epithet || fallback?.epithet || '红尘佳人',
      tagline,
      tags: derivedTags,
      realm,
      realmColor: inferColorFromRealmText(realm),
      spiritRoot: lore?.spiritRoot || fallback?.spiritRoot || '待探知',
      physique: lore?.physique || fallback?.physique || '待探知',
      affiliation: lore?.affiliation || fallback?.affiliation || '五域山海',
      weapon: lore?.weapon || fallback?.weapon || '随身法器',
      ageDesc: lore?.ageDesc || '',
      appearanceNote: lore?.appearanceNote || '',
      temperamentNote: lore?.temperamentNote || '',
      frontImages: images.frontImages,
      backImages: images.backImages,
      ...(images.dualSoulPortraits ? { dualSoulPortraits: images.dualSoulPortraits } : {}),
      defaultQuote: heroineOpenings.find(o => o.quote)?.quote || fallback?.defaultQuote || tagline,
      openings: heroineOpenings,
    };
  });

  // 将有专属开局的红颜排在前列，保持预设顺序稳定
  heroines.sort((a, b) => {
    const aHas = a.openings.length > 0 ? 1 : 0;
    const bHas = b.openings.length > 0 ? 1 : 0;
    if (aHas !== bHas) return bHas - aHas;
    const aOrder = HEROINE_ORDER.indexOf(a.name as (typeof HEROINE_ORDER)[number]);
    const bOrder = HEROINE_ORDER.indexOf(b.name as (typeof HEROINE_ORDER)[number]);
    if (aOrder >= 0 && bOrder >= 0) return aOrder - bOrder;
    if (aOrder >= 0) return -1;
    if (bOrder >= 0) return 1;
    return a.name.localeCompare(b.name, 'zh-Hans-CN');
  });

  const guideOpening = openings.find(item => item.kind === 'guide') ?? null;
  const customOpenings = openings.filter(item => item.kind === 'custom');
  const selectableOpenings = openings.filter(item => item.kind !== 'guide');

  cachedKey = signature;
  cachedCatalog = {
    characterName,
    worldbookName,
    guideNote,
    guideOpening,
    customOpenings,
    openings,
    selectableOpenings,
    heroines,
  };
  return cachedCatalog;
}
