sition: all 0.15s ease;\n\n    &.active {\n      color: var(--gold);\n      background: var(--button-active);\n    }\n  }\n}\n\n.portrait-side-pill {\n  position: absolute;\n  top: 10px;\n  right: 10px;\n  z-index: 4;\n  padding: 3px 9px;\n  border: 1px solid var(--line-subtle);\n  border-radius: 999px;\n  color: var(--text-accent);\n  background: color-mix(in srgb, var(--surface-raised) 82%, transparent);\n  backdrop-filter: blur(8px);\n  font-size: 10px;\n  font-variant-numeric: tabular-nums;\n  pointer-events: none;\n}\n\n.portrait-frame-box {\n  position: relative;\n  z-index: 2;\n  width: 100%;\n  height: clamp(275px, 44dvh, 396px);\n  padding: 10px 14px 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  overflow: hidden;\n}\n\n.portrait-main-img {\n  width: auto;\n  max-width: 100%;\n  height: 100%;\n  aspect-ratio: 2 / 3;\n  object-fit: cover;\n  object-position: center top;\n  border-radius: 9px 9px 0 0;\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);\n  transition: transform 0.35s ease;\n}\n\n.portrait-frame-box:hover .portrait-main-img {\n  transform: scale(1.02);\n}\n\n.portrait-fallback {\n  display: grid;\n  place-items: center;\n  gap: 6px;\n  color: var(--text-secondary);\n\n  span {\n    width: 64px;\n    height: 64px;\n    display: grid;\n    place-items: center;\n    border: 1px solid var(--line-strong);\n    border-radius: 50%;\n    color: var(--gold);\n    font-size: 26px;\n    font-weight: 700;\n  }\n  small {\n    font-size: 11px;\n  }\n}\n\n.portrait-bottom-gradient {\n  position: absolute;\n  inset-inline: 0;\n  bottom: 0;\n  padding: 28px 14px 11px;\n  background: linear-gradient(180deg, transparent 0%, rgba(6, 12, 18, 0.78) 52%, rgba(4, 9, 14, 0.94) 100%);\n  color: #f6f1e7;\n}\n\n.portrait-title-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n\n  h3 {\n    margin: 0;\n    font-size: 18px;\n    font-weight: 700;\n    letter-spacing: 0.04em;\n    co