import { defineStore } from 'pinia';
import { loadGreetingCatalog, } from './catalog';
import { executeSwitchOpening, readGreetingChatRuntimeState } from './switcher';
import { buildThemeStyleVars, getThemeById, readReduceMotionPreference, readSyncedThemeId, } from './theme-bridge';
export const useGreetingIndexStore = defineStore('dhl-greeting-index', () => {
    const visible = ref(false);
    const loading = ref(false);
    const switchingIndex = ref(null);
    const viewMode = ref('heroine');
    const selectedRoster = ref('');
    const searchQuery = ref('');
    const allFilterHeroine = ref('all');
    // 立绘浏览状态
    const portraitIndex = ref(0);
    const portraitFlipped = ref(false);
    const activeDualSoul = ref('虞汐');
    const lightboxOpen = ref(false);
    // 序章原文预览与中途切换确认
    const previewOpening = ref(null);
    const pendingConfirmOpening = ref(null);
    // 主题同步
    const themeId = ref(readSyncedThemeId());
    const reduceMotion = ref(readReduceMotionPreference());
    const currentTheme = computed(() => getThemeById(themeId.value));
    const themeStyleVars = computed(() => buildThemeStyleVars(currentTheme.value));
    // 数据目录与聊天实时状态
    const catalog = ref({
        characterName: '',
        worldbookName: '',
        guideNote: '',
        guideOpening: null,
        customOpenings: [],
        openings: [],
        selectableOpenings: [],
        heroines: [],
    });
    const runtime = ref({
        hasSwipeFloor: false,
        greetingMessageId: 0,
        currentSwipeId: null,
        currentIndex: null,
        lastMessageId: -1,
        laterMessageCount: 0,
    });
    const currentOpening = computed(() => {
        if (runtime.value.currentIndex === null)
            return null;
        return catalog.value.openings.find(item => item.index === runtime.value.currentIndex) ?? null;
    });
    const activeHeroine = computed(() => {
        if (selectedRoster.value === '__custom__' || selectedRoster.value === '__guide__')
            return null;
        return (catalog.value.heroines.find(h => h.name === selectedRoster.value) ??
            catalog.value.heroines[0] ??
            null);
    });
    const activeFrontPool = computed(() => {
        const heroine = activeHeroine.value;
        if (!heroine)
            return [];
        if (heroine.dualSoulPortraits) {
            return heroine.dualSoulPortraits[activeDualSoul.value].front;
        }
        return heroine.frontImages;
    });
    const activeBackPool = computed(() => {
        const heroine = activeHeroine.value;
        if (!heroine)
            return [];
        if (heroine.dualSoulPortraits) {
            return heroine.dualSoulPortraits[activeDualSoul.value].back;
        }
        return heroine.backImages;
    });
    const currentPortraitPool = computed(() => portraitFlipped.value ? activeBackPool.value : activeFrontPool.value);
    const currentPortraitUrl = computed(() => {
        const pool = currentPortraitPool.value;
        if (pool.length === 0)
            return '';
        const safeIndex = ((portraitIndex.value % pool.length) + pool.length) % pool.length;
        return pool[safeIndex] ?? '';
    });
    const syncTheme = () => {
        themeId.value = readSyncedThemeId();
        reduceMotion.value = readReduceMotionPreference();
    };
    const refreshRuntime = () => {
        runtime.value = readGreetingChatRuntimeState(catalog.value.openings);
    };
    const resetPortraitState = () => {
        portraitIndex.value = 0;
        portraitFlipped.value = false;
    };
    const selectRoster = (target) => {
        if (selectedRoster.value === target)
            return;
        selectedRoster.value = target;
        resetPortraitState();
    };
    const stepPortrait = (delta) => {
        const pool = currentPortraitPool.value;
        if (pool.length <= 1)
            return;
        if (delta === 'random') {
            let next = Math.floor(Math.random() * pool.length);
            if (next === portraitIndex.value % pool.length) {
                next = (next + 1) % pool.length;
            }
            portraitIndex.value = next;
            return;
        }
        portraitIndex.value = ((portraitIndex.value + delta) % pool.length + pool.length) % pool.length;
    };
    const togglePortraitFlip = () => {
        portraitFlipped.value = !portraitFlipped.value;
        portraitIndex.value = 0;
    };
    const setDualSoul = (soul) => {
        if (activeDualSoul.value === soul)
            return;
        activeDualSoul.value = soul;
        portraitIndex.value = 0;
    };
    const getHeroineThumbnail = (heroineName) => {
        if (!heroineName)
            return '';
        const profile = catalog.value.heroines.find(item => item.name === heroineName);
        return profile?.frontImages[0] ?? '';
    };
    const refreshCatalog = async (force = false) => {
        loading.value = true;
        try {
            catalog.value = await loadGreetingCatalog(force);
            refreshRuntime();
        }
        finally {
            loading.value = false;
        }
    };
    const applyDefaultSelection = (options) => {
        if (options?.view) {
            viewMode.value = options.view;
        }
        else {
            viewMode.value = 'heroine';
        }
        searchQuery.value = options?.query?.trim() ?? '';
        allFilterHeroine.value = 'all';
        if (options?.heroine) {
            const matched = catalog.value.heroines.find(h => h.name === options.heroine);
            if (matched) {
                selectRoster(matched.name);
                return;
            }
        }
        const current = currentOpening.value;
        if (current?.kind === 'heroine' && current.heroineName) {
            selectRoster(current.heroineName);
            return;
        }
        if (current?.kind === 'custom') {
            selectRoster('__custom__');
            return;
        }
        if (catalog.value.heroines.length > 0) {
            selectRoster(catalog.value.heroines[0].name);
        }
        else if (catalog.value.customOpenings.length > 0) {
            selectRoster('__custom__');
        }
        else if (catalog.value.guideOpening) {
            selectRoster('__guide__');
        }
    };
    const locateCurrentOpening = () => {
        refreshRuntime();
        const current = currentOpening.value;
        if (!current) {
            toastr.info('当前尚未定位到对应的额外开场白。');
            return;
        }
        if (viewMode.value === 'all') {
            searchQuery.value = '';
            allFilterHeroine.value = current.heroineName ?? (current.kind === 'custom' ? '__custom__' : 'all');
            return;
        }
        if (current.kind === 'heroine' && current.heroineName) {
            selectRoster(current.heroineName);
        }
        else if (current.kind === 'custom') {
            selectRoster('__custom__');
        }
        else if (current.kind === 'guide') {
            selectRoster('__guide__');
        }
    };
    const open = async (options) => {
        syncTheme();
        previewOpening.value = null;
        pendingConfirmOpening.value = null;
        lightboxOpen.value = false;
        visible.value = true;
        await refreshCatalog(false);
        applyDefaultSelection(options);
        if (options?.locateCurrent) {
            locateCurrentOpening();
        }
    };
    const close = () => {
        if (switchingIndex.value !== null)
            return;
        lightboxOpen.value = false;
        previewOpening.value = null;
        pendingConfirmOpening.value = null;
        visible.value = false;
    };
    const toggle = async (options) => {
        if (visible.value) {
            close();
            return;
        }
        await open(options);
    };
    const requestSwitchOpening = async (target) => {
        if (switchingIndex.value !== null)
            return;
        refreshRuntime();
        if (runtime.value.currentIndex === target.index && runtime.value.laterMessageCount === 0) {
            close();
            return;
        }
        if (runtime.value.laterMessageCount > 0) {
            pendingConfirmOpening.value = target;
            return;
        }
        await performSwitch(target, false);
    };
    const confirmMidChatSwitch = async () => {
        const target = pendingConfirmOpening.value;
        if (!target || switchingIndex.value !== null)
            return;
        await performSwitch(target, true);
    };
    const performSwitch = async (target, clearLaterMessages) => {
        switchingIndex.value = target.index;
        try {
            const ok = await executeSwitchOpening(target, { clearLaterMessages });
            if (ok) {
                pendingConfirmOpening.value = null;
                previewOpening.value = null;
                refreshRuntime();
                visible.value = false;
            }
        }
        catch (error) {
            console.error('[开场白索引] 切换开局失败', error);
            toastr.error('切换开局失败，请查看控制台日志。');
        }
        finally {
            switchingIndex.value = null;
        }
    };
    const inspectHeroineFromAllView = (heroineName) => {
        viewMode.value = 'heroine';
        selectRoster(heroineName);
    };
    return {
        visible,
        loading,
        switchingIndex,
        viewMode,
        selectedRoster,
        searchQuery,
        allFilterHeroine,
        portraitIndex,
        portraitFlipped,
        activeDualSoul,
        lightboxOpen,
        previewOpening,
        pendingConfirmOpening,
        themeId,
        reduceMotion,
        currentTheme,
        themeStyleVars,
        catalog,
        runtime,
        currentOpening,
        activeHeroine,
        activeFrontPool,
        activeBackPool,
        currentPortraitPool,
        currentPortraitUrl,
        syncTheme,
        refreshRuntime,
        refreshCatalog,
        selectRoster,
        stepPortrait,
        togglePortraitFlip,
        setDualSoul,
        getHeroineThumbnail,
        locateCurrentOpening,
        open,
        close,
        toggle,
        requestSwitchOpening,
        confirmMidChatSwitch,
        inspectHeroineFromAllView,
    };
});
