import { getDefaultTheme, getThemeById, isThemeId, type Theme, type ThemeId } from '../灯火通明-测试版/themes';
import duskInkArt from '../灯火通明-测试版/assets/dusk-ink-landscape.svg?url';
import lanternArt from '../灯火通明-测试版/assets/lantern-water-town.svg?url';
import peachPuddingArt from '../灯火通明-测试版/assets/peach-pudding-doodle.svg?url';
import shanhaiArt from '../灯火通明-测试版/assets/shanhai-scroll.svg?url';
import starrailGlassArt from '../灯火通明-测试版/assets/starrail-glass-aurora.svg?url';
import velvetOperaArt from '../灯火通明-测试版/assets/velvet-opera-rose.svg?url';

const THEME_STORAGE_KEY = 'dhl-theme-id-v2';
const LEGACY_THEME_KEYS = ['ui_theme_id', 'dhl-theme-id-v1'] as const;
const PREFERENCES_STORAGE_KEY = 'dhl-reading-preferences-v1';

const THEME_ART_MAP: Record<ThemeId, string> = {
  lantern: lanternArt,
  duskInk: duskInkArt,
  shanhai: shanhaiArt,
  peachPudding: peachPuddingArt,
  starrailGlass: starrailGlassArt,
  velvetOpera: velvetOperaArt,
};

function resolveStorage(): Storage | null {
  try {
    return window.parent?.localStorage ?? window.localStorage;
  } catch {
    try {
      return window.localStorage;
    } catch {
      return null;
    }
  }
}

export function readSyncedThemeId(): ThemeId {
  const storage = resolveStorage();
  if (!storage) return getDefaultTheme().id;

  try {
    const raw = storage.getItem(THEME_STORAGE_KEY);
    if (isThemeId(raw)) return raw;
    if (raw === 'starAltar') return 'starrailGlass';

    for (const key of LEGACY_THEME_KEYS) {
      const legacy = storage.getItem(key);
      if (isThemeId(legacy)) return legacy;
      if (legacy === 'starAltar') return 'starrailGlass';
      if (legacy === 'red') return getDefaultTheme().id;
    }
  } catch {
    return getDefaultTheme().id;
  }

  return getDefaultTheme().id;
}

export function readReduceMotionPreference(): boolean {
  const storage = resolveStorage();
  try {
    const raw = storage?.getItem(PREFERENCES_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as { reduceMotion?: unknown };
      if (typeof parsed.reduceMotion === 'boolean') return parsed.reduceMotion;
    }
  } catch {
    // ignore invalid cache
  }
  return window.matchMedia?.('(prefers-reduced-motion: reduce)').matches ?? false;
}

